import{_ as l,a0 as p,w as r,s as d,I as a,x as s,a1 as e,A as t,ao as i}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const x=JSON.parse('{"title":"在 Linux 中怎麼使用 cron 計劃任務 | LCTT x X-CMD","titleTemplate":false,"description":"在 Linux 中怎麼使用 cron 計劃任務 | LCTT (201711) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 Linux 中怎麼使用 cron 計劃任務 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 Linux 中怎麼使用 cron 計劃任務 | LCTT (201711) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201711/20171101 How to use cron in Linux","title":"在 Linux 中怎麼使用 cron 計劃任務","tag":"201711","desc":""},"relativePath":"201711/20171101 How to use cron in Linux.md","filePath":"[post].md"}'),c={name:"201711/20171101 How to use cron in Linux.md"};function u(b,n,h,g,k,m){const o=p("Link");return r(),d("div",null,[n[52]||(n[52]=a("h1",{id:"在-linux-中怎麼使用-cron-計劃任務",tabindex:"-1"},[s("在 Linux 中怎麼使用 cron 計劃任務 "),a("a",{class:"header-anchor",href:"#在-linux-中怎麼使用-cron-計劃任務","aria-label":"Permalink to “在 Linux 中怎麼使用 cron 計劃任務”"},"​")],-1)),n[53]||(n[53]=a("blockquote",null,[a("p",null,"沒有時間運行命令？使用 cron 的計劃任務意味着你不用熬夜程序也可以運行。")],-1)),a("p",null,[n[2]||(n[2]=a("img",{src:"https://opensource.com/sites/default/files/styles/image-full-size/public/lead-images/linux-penguins.png?itok=yKOpaJM_",alt:"How to use cron in Linux",title:"How to use cron in Linux"},null,-1)),n[3]||(n[3]=s(" Image by : ",-1)),e(o,{href:"https://www.flickr.com/photos/internetarchivebookimages/20570945848/in/photolist-xkMtw9-xA5zGL-tEQLWZ-wFwzFM-aNwxgn-aFdWBj-uyFKYv-7ZCCBU-obY1yX-UAPafA-otBzDF-ovdDo6-7doxUH-obYkeH-9XbHKV-8Zk4qi-apz7Ky-apz8Qu-8ZoaWG-orziEy-aNwxC6-od8NTv-apwpMr-8Zk4vn-UAP9Sb-otVa3R-apz6Cb-9EMPj6-eKfyEL-cv5mwu-otTtHk-7YjK1J-ovhxf6-otCg2K-8ZoaJf-UAPakL-8Zo8j7-8Zk74v-otp4Ls-8Zo8h7-i7xvpR-otSosT-9EMPja-8Zk6Zi-XHpSDB-hLkuF3-of24Gf-ouN1Gv-fJzkJS-icfbY9"},{default:t(()=>[...n[0]||(n[0]=[s("Internet Archive Book Images",-1)])]),_:1}),n[4]||(n[4]=s(". Modified by Opensource.com. ",-1)),e(o,{href:"https://creativecommons.org/licenses/by-sa/4.0/"},{default:t(()=>[...n[1]||(n[1]=[s("CC BY-SA 4.0",-1)])]),_:1})]),n[54]||(n[54]=a("p",null,"系統管理員（在許多好處中）的挑戰之一是在你該睡覺的時候去運行一些任務。例如，一些任務（包括定期循環運行的任務）需要在沒有人使用計算機資源的時候去運行，如午夜或週末。在下班後，我沒有時間去運行命令或腳本。而且，我也不想在晚上去啓動備份或重大更新。",-1)),a("p",null,[n[6]||(n[6]=s("取而代之的是，我使用兩個服務功能在我預定的時間去運行命令、程序和任務。",-1)),e(o,{href:"https://en.wikipedia.org/wiki/Cron"},{default:t(()=>[...n[5]||(n[5]=[s("cron",-1)])]),_:1}),n[7]||(n[7]=s(" 和 at 服務允許系統管理員去安排任務運行在未來的某個特定時間。at 服務指定在某個時間去運行一次任務。cron 服務可以安排任務在一個週期上重複，比如天、周、或月。",-1))]),n[55]||(n[55]=a("p",null,"在這篇文章中，我將介紹 cron 服務和怎麼去使用它。",-1)),n[56]||(n[56]=a("h3",{id:"常見-和非常見-的-cron-用途",tabindex:"-1"},[s("常見（和非常見）的 cron 用途 "),a("a",{class:"header-anchor",href:"#常見-和非常見-的-cron-用途","aria-label":"Permalink to “常見（和非常見）的 cron 用途”"},"​")],-1)),n[57]||(n[57]=a("p",null,"我使用 cron 服務去安排一些常見的事情，比如，每天凌晨 2:00 發生的定期備份，我也使用它去做一些不常見的事情。",-1)),a("ul",null,[n[15]||(n[15]=a("li",null,"許多電腦上的系統時鐘（比如，操作系統時間）都設置為使用網絡時間協議（NTP）。 NTP 設置系統時間後，它不會去設置硬件時鐘，它可能會“漂移”。我使用 cron 基於系統時間去設置硬件時鐘。",-1)),n[16]||(n[16]=a("li",null,"我還有一個 Bash 程序，我在每天早晨運行它，去在每台電腦上創建一個新的 “每日信息” （MOTD）。它包含的信息有當前的磁盤使用情況等有用的信息。",-1)),a("li",null,[n[11]||(n[11]=s("許多系統進程和服務，像 ",-1)),e(o,{href:"https://sourceforge.net/projects/logwatch/files/"},{default:t(()=>[...n[8]||(n[8]=[s("Logwatch",-1)])]),_:1}),n[12]||(n[12]=s("、",-1)),e(o,{href:"https://github.com/logrotate/logrotate"},{default:t(()=>[...n[9]||(n[9]=[s("logrotate",-1)])]),_:1}),n[13]||(n[13]=s("、和 ",-1)),e(o,{href:"http://rkhunter.sourceforge.net/"},{default:t(()=>[...n[10]||(n[10]=[s("Rootkit Hunter",-1)])]),_:1}),n[14]||(n[14]=s("，使用 cron 服務去安排任務和每天運行程序。",-1))])]),n[58]||(n[58]=i(`<p>crond 守護進程是一個完成 cron 功能的後台服務。</p><p>cron 服務檢查在 <code>/var/spool/cron</code> 和 <code>/etc/cron.d</code> 目錄中的文件，以及 <code>/etc/anacrontab</code> 文件。這些文件的內容定義了以不同的時間間隔運行的 cron 作業。個體用户的 cron 文件是位於 <code>/var/spool/cron</code>，而系統服務和應用生成的 cron 作業文件放在 <code>/etc/cron.d</code> 目錄中。<code>/etc/anacrontab</code> 是一個特殊的情況，它將在本文中稍後部分介紹。</p><h3 id="使用-crontab" tabindex="-1">使用 crontab <a class="header-anchor" href="#使用-crontab" aria-label="Permalink to “使用 crontab”">​</a></h3><p>cron 實用程序運行基於一個 cron 表（<code>crontab</code>）中指定的命令。每個用户，包括 root，都有一個 cron 文件。這些文件缺省是不存在的。但可以使用 <code>crontab -e</code> 命令創建在 <code>/var/spool/cron</code> 目錄中，也可以使用該命令去編輯一個 cron 文件（看下面的腳本）。我強烈建議你，_不要_使用標準的編輯器（比如，Vi、Vim、Emacs、Nano、或者任何其它可用的編輯器）。使用 <code>crontab</code> 命令不僅允許你去編輯命令，也可以在你保存並退出編輯器時，重啓動 crond 守護進程。<code>crontab</code> 命令使用 Vi 作為它的底層編輯器，因為 Vi 是預裝的（至少在大多數的基本安裝中是預裝的）。</p><p>現在，cron 文件是空的，所以必須從頭添加命令。 我增加下面示例中定義的作業到我的 cron 文件中，這是一個快速指南，以便我知道命令中的各個部分的意思是什麼，你可以自由拷貝它，供你自己使用。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># crontab -e</span></span>
<span class="line"><span>SHELL=/bin/bash</span></span>
<span class="line"><span>MAILTO=root@example.com</span></span>
<span class="line"><span>PATH=/bin:/sbin:/usr/bin:/usr/sbin:/usr/local/bin:/usr/local/sbin</span></span>
<span class="line"><span></span></span>
<span class="line"><span># For details see man 4 crontabs</span></span>
<span class="line"><span></span></span>
<span class="line"><span># Example of job definition:</span></span>
<span class="line"><span># .---------------- minute (0 - 59)</span></span>
<span class="line"><span># |  .------------- hour (0 - 23)</span></span>
<span class="line"><span># |  |  .---------- day of month (1 - 31)</span></span>
<span class="line"><span># |  |  |  .------- month (1 - 12) OR jan,feb,mar,apr ...</span></span>
<span class="line"><span># |  |  |  |  .---- day of week (0 - 6) (Sunday=0 or 7) OR sun,mon,tue,wed,thu,fri,sat</span></span>
<span class="line"><span># |  |  |  |  |</span></span>
<span class="line"><span># *  *  *  *  * user-name  command to be executed</span></span>
<span class="line"><span></span></span>
<span class="line"><span># backup using the rsbu program to the internal 4TB HDD and then 4TB external</span></span>
<span class="line"><span>01 01 * * * /usr/local/bin/rsbu -vbd1 ; /usr/local/bin/rsbu -vbd2</span></span>
<span class="line"><span></span></span>
<span class="line"><span># Set the hardware clock to keep it in sync with the more accurate system clock</span></span>
<span class="line"><span>03 05 * * * /sbin/hwclock --systohc</span></span>
<span class="line"><span></span></span>
<span class="line"><span># Perform monthly updates on the first of the month</span></span>
<span class="line"><span># 25 04 1 * * /usr/bin/dnf -y update</span></span></code></pre></div><p><em><code>crontab</code> 命令用於查看或編輯 cron 文件。</em></p><p>上面代碼中的前三行設置了一個缺省環境。對於給定用户，環境變量必須是設置的，因為，cron 不提供任何方式的環境。<code>SHELL</code> 變量指定命令運行使用的 shell。這個示例中，指定為 Bash shell。<code>MAILTO</code> 變量設置發送 cron 作業結果的電子郵件地址。這些電子郵件提供了 cron 作業（備份、更新、等等）的狀態，和你從命令列中手動運行程序時看到的結果是一樣的。第三行為環境設置了 <code>PATH</code> 變量。但即使在這裏設置了路徑，我總是使用每個程序的完全限定路徑。</p><p>在上面的示例中有幾個註釋行，它詳細説明了定義一個 cron 作業所要求的語法。我將在下面分別講解這些命令，然後，增加更多的 crontab 文件的高級特性。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>01 01 * * * /usr/local/bin/rsbu -vbd1 ; /usr/local/bin/rsbu -vbd2</span></span></code></pre></div><p><em>在我的 <code>/etc/crontab</code> 中的這一行運行一個腳本，用於為我的系統執行備份。</em></p><p>這一行運行我自己編寫的 Bash shell 腳本 <code>rsbu</code>，它對我的系統做完全備份。這個作業每天的凌晨 1:01 (<code>01 01</code>) 運行。在這三、四、五位置上的星號（*），像文件通配符一樣代表一個特定的時間，它們代表 “一個月中的每天”、“每個月” 和 “一週中的每天”，這一行會運行我的備份兩次，一次備份內部專用的硬盤驅動器，另外一次運行是備份外部的 USB 驅動器，使用它這樣我可以很保險。</p><p>接下來的行我設置了一個硬件時鐘，它使用當前系統時鐘作為源去設置硬件時鐘。這一行設置為每天凌晨 5：03 分運行。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>03 05 * * * /sbin/hwclock --systohc</span></span></code></pre></div><p><em>這一行使用系統時間作為源來設置硬件時鐘。</em></p><p>我使用的第三個也是最後一個的 cron 作業是去執行一個 <code>dnf</code> 或 <code>yum</code> 更新，它在每個月的第一天的凌晨 04:25 運行，但是，我註釋掉了它，以後不再運行。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># 25 04 1 * * /usr/bin/dnf -y update</span></span></code></pre></div><p><em>這一行用於執行一個每月更新，但是，我也把它註釋掉了。</em></p><h4 id="其它的定時任務技巧" tabindex="-1">其它的定時任務技巧 <a class="header-anchor" href="#其它的定時任務技巧" aria-label="Permalink to “其它的定時任務技巧”">​</a></h4><p>現在，讓我們去做一些比基本知識更有趣的事情。假設你希望在每週四下午 3:00 去運行一個特別的作業：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>00 15 * * Thu /usr/local/bin/mycronjob.sh</span></span></code></pre></div><p>這一行會在每週四下午 3:00 運行 <code>mycronjob.sh</code> 這個腳本。</p><p>或者，或許你需要在每個季度末去運行一個季度報告。cron 服務沒有為 “每個月的最後一天” 設置選項，因此，替代方式是使用下一個月的第一天，像如下所示（這裏假設當作業準備運行時，報告所需要的數據已經準備好了）。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>02 03 1 1,4,7,10 * /usr/local/bin/reports.sh</span></span></code></pre></div><p><em>在季度末的下一個月的第一天運行這個 cron 作業。</em></p><p>下面展示的這個作業，在每天的上午 9:01 到下午 5:01 之間，每小時運行一次。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>01 09-17 * * * /usr/local/bin/hourlyreminder.sh</span></span></code></pre></div><p><em>有時，你希望作業在業務期間定時運行。</em></p><p>我遇到一個情況，需要作業在每二、三或四小時去運行。它需要用期望的間隔去劃分小時，比如， <code>*/3</code> 為每三個小時，或者 <code>6-18/3</code> 為上午 6 點到下午 6 點每三個小時運行一次。其它的時間間隔的劃分也是類似的。例如，在分鐘位置的表達式 <code>*/15</code> 意思是 “每 15 分鐘運行一次作業”。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>*/5 08-18/2 * * * /usr/local/bin/mycronjob.sh</span></span></code></pre></div><p><em>這個 cron 作業在上午 8:00 到下午 18:59 之間，每五分鐘運行一次作業。</em></p><p>需要注意的一件事情是：除法表達式的結果必須是餘數為 0（即整除）。換句話説，在這個例子中，這個作業被設置為在上午 8 點到下午 6 點之間的偶數小時每 5 分鐘運行一次（08:00、08:05、 08:10、 08:15……18:55 等等），而不運行在奇數小時。另外，這個作業不能運行在下午 7:00 到上午 7:59 之間。（LCTT 譯註：此處本文表述有誤，根據正確情況修改）</p><p>我相信，你可以根據這些例子想到許多其它的可能性。</p><h4 id="限制訪問-cron" tabindex="-1">限制訪問 cron <a class="header-anchor" href="#限制訪問-cron" aria-label="Permalink to “限制訪問 cron”">​</a></h4><p>普通用户使用 cron 訪問可能會犯錯誤，例如，可能導致系統資源（比如內存和 CPU 時間）被耗盡。為避免這種可能的問題， 系統管理員可以通過創建一個 <code>/etc/cron.allow</code> 文件去限制用户訪問，它包含了一個允許去創建 cron 作業的用户列表。（不管是否列在這個列表中，）不能阻止 root 用户使用 cron。</p><p>通過阻止非 root 用户創建他們自己的 cron 作業，那也許需要將非 root 用户的 cron 作業添加到 root 的 crontab 中， “但是，等等！” 你説，“不是以 root 去運行這些作業？” 不一定。在這篇文章中的第一個示例中，出現在註釋中的用户名字段可以用於去指定一個運行作業的用户 ID。這可以防止特定的非 root 用户的作業以 root 身份去運行。下面的示例展示了一個作業定義，它以 “student” 用户去運行這個作業：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>04 07 * * * student /usr/local/bin/mycronjob.sh</span></span></code></pre></div><p>如果沒有指定用户，這個作業將以 contab 文件的所有者用户去運行，在這個情況中是 root。</p><h4 id="cron-d" tabindex="-1">cron.d <a class="header-anchor" href="#cron-d" aria-label="Permalink to “cron.d”">​</a></h4>`,39)),a("p",null,[n[19]||(n[19]=s("目錄 ",-1)),n[20]||(n[20]=a("code",null,"/etc/cron.d",-1)),n[21]||(n[21]=s(" 中是一些應用程序，比如 ",-1)),e(o,{href:"http://spamassassin.apache.org/"},{default:t(()=>[...n[17]||(n[17]=[s("SpamAssassin",-1)])]),_:1}),n[22]||(n[22]=s(" 和 ",-1)),e(o,{href:"https://github.com/sysstat/sysstat"},{default:t(()=>[...n[18]||(n[18]=[s("sysstat",-1)])]),_:1}),n[23]||(n[23]=s(" 安裝的 cron 文件。因為，這裏沒有 spamassassin 或者 sysstat 用户，這些程序需要一個位置去放置 cron 文件，因此，它們被放在 ",-1)),n[24]||(n[24]=a("code",null,"/etc/cron.d",-1)),n[25]||(n[25]=s(" 中。",-1))]),n[59]||(n[59]=i(`<p>下面的 <code>/etc/cron.d/sysstat</code> 文件包含系統活動報告（SAR）相關的 cron 作業。這些 cron 文件和用户 cron 文件格式相同。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># Run system activity accounting tool every 10 minutes</span></span>
<span class="line"><span>*/10 * * * * root /usr/lib64/sa/sa1 1 1</span></span>
<span class="line"><span># Generate a daily summary of process accounting at 23:53</span></span>
<span class="line"><span>53 23 * * * root /usr/lib64/sa/sa2 -A</span></span></code></pre></div><p><em>sysstat 包安裝了 <code>/etc/cron.d/sysstat</code> cron 文件來運行程序生成 SAR。</em></p><p>該 sysstat cron 文件有兩行執行任務。第一行每十分鐘去運行 <code>sa1</code> 程序去收集數據，存儲在 <code>/var/log/sa</code> 目錄中的一個指定的二進制文件中。然後，在每天晚上的 23:53， <code>sa2</code> 程序運行來創建一個每日彙總。</p><h4 id="計劃小貼士" tabindex="-1">計劃小貼士 <a class="header-anchor" href="#計劃小貼士" aria-label="Permalink to “計劃小貼士”">​</a></h4><p>我在 crontab 文件中設置的有些時間看上起似乎是隨機的，在某種程度上説，確實是這樣的。嘗試去安排 cron 作業可能是件很具有挑戰性的事， 尤其是作業的數量越來越多時。我通常在我的每個電腦上僅有一些任務，它比起我工作用的那些生產和實驗環境中的電腦簡單多了。</p><p>我管理的一個系統有 12 個每天晚上都運行 cron 作業，另外 3、4 個在週末或月初運行。那真是個挑戰，因為，如果有太多作業在同一時間運行，尤其是備份和編譯系統，會耗盡內存並且幾乎填滿交換文件空間，這會導致系統性能下降甚至是超負荷，最終什麼事情都完不成。我增加了一些內存並改進了如何計劃任務。我還刪除了一些寫的很糟糕、使用大量內存的任務。</p><p>crond 服務假設主機計算機 24 小時運行。那意味着如果在一個計劃運行的期間關閉計算機，這些計劃的任務將不再運行，直到它們計劃的下一次運行時間。如果這裏有關鍵的 cron 作業，這可能導致出現問題。 幸運的是，在定期運行的作業上，還有一個其它的選擇： <code>anacron</code>。</p><h3 id="anacron" tabindex="-1">anacron <a class="header-anchor" href="#anacron" aria-label="Permalink to “anacron”">​</a></h3>`,9)),a("p",null,[e(o,{href:"https://en.wikipedia.org/wiki/Anacron"},{default:t(()=>[...n[26]||(n[26]=[s("anacron",-1)])]),_:1}),n[27]||(n[27]=s(" 程序執行和 cron 一樣的功能，但是它增加了運行被跳過的作業的能力，比如，如果計算機已經關閉或者其它的原因導致無法在一個或多個週期中運行作業。它對筆記本電腦或其它被關閉或進行睡眠模式的電腦來説是非常有用的。",-1))]),n[60]||(n[60]=i(`<p>只要電腦一打開並引導成功，anacron 會檢查過去是否有計劃的作業被錯過。如果有，這些作業將立即運行，但是，僅運行一次（而不管它錯過了多少次循環運行）。例如，如果一個每週運行的作業在最近三週因為休假而系統關閉都沒有運行，它將在你的電腦一啓動就立即運行，但是，它僅運行一次，而不是三次。</p><p>anacron 程序提供了一些對週期性計劃任務很好用的選項。它是安裝在你的 <code>/etc/cron.[hourly|daily|weekly|monthly]</code> 目錄下的腳本。 根據它們需要的頻率去運行。</p><p>它是怎麼工作的呢？接下來的這些要比前面的簡單一些。</p><p>1、 crond 服務運行在 <code>/etc/cron.d/0hourly</code> 中指定的 cron 作業。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># Run the hourly jobs</span></span>
<span class="line"><span>SHELL=/bin/bash</span></span>
<span class="line"><span>PATH=/sbin:/bin:/usr/sbin:/usr/bin</span></span>
<span class="line"><span>MAILTO=root</span></span>
<span class="line"><span>01 * * * * root run-parts /etc/cron.hourly</span></span></code></pre></div><p><em><code>/etc/cron.d/0hourly</code> 中的內容使位於 <code>/etc/cron.hourly</code> 中的 shell 腳本運行。</em></p><p>2、 在 <code>/etc/cron.d/0hourly</code> 中指定的 cron 作業每小時運行一次 <code>run-parts</code> 程序。</p><p>3、 <code>run-parts</code> 程序運行所有的在 <code>/etc/cron.hourly</code> 目錄中的腳本。</p><p>4、 <code>/etc/cron.hourly</code> 目錄包含的 <code>0anacron</code> 腳本，它使用如下的 <code>/etdc/anacrontab</code> 配置文件去運行 anacron 程序。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># /etc/anacrontab: configuration file for anacron</span></span>
<span class="line"><span></span></span>
<span class="line"><span># See anacron(8) and anacrontab(5) for details.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>SHELL=/bin/sh</span></span>
<span class="line"><span>PATH=/sbin:/bin:/usr/sbin:/usr/bin</span></span>
<span class="line"><span>MAILTO=root</span></span>
<span class="line"><span># the maximal random delay added to the base delay of the jobs</span></span>
<span class="line"><span>RANDOM_DELAY=45</span></span>
<span class="line"><span># the jobs will be started during the following hours only</span></span>
<span class="line"><span>START_HOURS_RANGE=3-22</span></span>
<span class="line"><span></span></span>
<span class="line"><span>#period in days   delay in minutes   job-identifier   command</span></span>
<span class="line"><span>1       5       cron.daily              nice run-parts /etc/cron.daily</span></span>
<span class="line"><span>7       25      cron.weekly             nice run-parts /etc/cron.weekly</span></span>
<span class="line"><span>@monthly 45     cron.monthly            nice run-parts /etc/cron.monthly</span></span></code></pre></div><p><em><code>/etc/anacrontab</code> 文件中的內容在合適的時間運行在 <code>cron.[daily|weekly|monthly]</code> 目錄中的可執行文件。</em></p><p>5、 anacron 程序每日運行一次位於 <code>/etc/cron.daily</code> 中的作業。它每週運行一次位於 <code>/etc/cron.weekly</code> 中的作業。以及每月運行一次 <code>cron.monthly</code> 中的作業。注意，在每一行指定的延遲時間，它可以幫助避免這些作業與其它 cron 作業重疊。</p><p>我在 <code>/usr/local/bin</code> 目錄中放置它們，而不是在 <code>cron.X</code> 目錄中放置完整的 Bash 程序，這會使我從命令列中運行它們更容易。然後，我在 cron 目錄中增加一個符號連接，比如，<code>/etc/cron.daily</code>。</p><p>anacron 程序不是設計用於在指定時間運行程序的。而是，用於在一個指定的時間開始，以一定的時間間隔去運行程序，比如，從每天的凌晨 3:00（看上面腳本中的 <code>START_HOURS_RANGE</code> 行）、從週日（每週第一天）和這個月的第一天。如果任何一個或多個循環錯過，anacron 將立即運行這個錯過的作業。</p><h3 id="更多的關於設置限制" tabindex="-1">更多的關於設置限制 <a class="header-anchor" href="#更多的關於設置限制" aria-label="Permalink to “更多的關於設置限制”">​</a></h3><p>我在我的計算機上使用了很多運行計劃任務的方法。所有的這些任務都需要一個 root 權限去運行。在我的經驗中，很少有普通用户去需要運行 cron 任務，一種情況是開發人員需要一個 cron 作業去啓動一個開發實驗室的每日編譯。</p><p>限制非 root 用户去訪問 cron 功能是非常重要的。然而，在一些特殊情況下，用户需要去設置一個任務在預先指定時間運行，而 cron 可以允許他們去那樣做。許多用户不理解如何正確地配置 cron 去完成任務，並且他們會出錯。這些錯誤可能是無害的，但是，往往不是這樣的，它們可能導致問題。通過設置功能策略，使用户與管理員互相配合，可以使個別的 cron 作業儘可能地不干擾其它的用户和系統功能。</p><p>可以給為單個用户或組分配的資源設置限制，但是，這是下一篇文章中的內容。</p>`,18)),a("p",null,[n[33]||(n[33]=s("更多信息，在 ",-1)),e(o,{href:"http://man7.org/linux/man-pages/man8/cron.8.html"},{default:t(()=>[...n[28]||(n[28]=[s("cron",-1)])]),_:1}),n[34]||(n[34]=s("、",-1)),e(o,{href:"http://man7.org/linux/man-pages/man5/crontab.5.html"},{default:t(()=>[...n[29]||(n[29]=[s("crontab",-1)])]),_:1}),n[35]||(n[35]=s("、",-1)),e(o,{href:"http://man7.org/linux/man-pages/man8/anacron.8.html"},{default:t(()=>[...n[30]||(n[30]=[s("anacron",-1)])]),_:1}),n[36]||(n[36]=s("、",-1)),e(o,{href:"http://man7.org/linux/man-pages/man5/anacrontab.5.html"},{default:t(()=>[...n[31]||(n[31]=[s("anacrontab",-1)])]),_:1}),n[37]||(n[37]=s("、和 ",-1)),e(o,{href:"http://manpages.ubuntu.com/manpages/zesty/man8/run-parts.8.html"},{default:t(()=>[...n[32]||(n[32]=[s("run-parts",-1)])]),_:1}),n[38]||(n[38]=s(" 的 man 頁面上，所有的這些信息都描述了 cron 系統是如何工作的。",-1))]),n[61]||(n[61]=a("hr",null,null,-1)),n[62]||(n[62]=a("p",null,"作者簡介：",-1)),n[63]||(n[63]=a("p",null,"David Both - 是一位 Linux 和開源軟件的倡導者，居住在 Raleigh，North Carolina。他從事 IT 行業超過四十年，並且在 IBM 教授 OS/2 超過 20 年時間，他在 1981 年 IBM 期間，為最初的 IBM PC 寫了第一部培訓教程。他為 Red Hat 教授 RHCE 系列課程，並且他也為 MCI Worldcom、 Cisco、和 North Carolina 州工作。他使用 Linux 和開源軟件工作差不多 20 年了。",-1)),n[64]||(n[64]=a("hr",null,null,-1)),a("p",null,[n[40]||(n[40]=s("via: ",-1)),e(o,{href:"https://opensource.com/article/17/11/how-use-cron-linux"},{default:t(()=>[...n[39]||(n[39]=[s("https://opensource.com/article/17/11/how-use-cron-linux",-1)])]),_:1})]),a("p",null,[n[44]||(n[44]=s("作者：",-1)),e(o,{href:"https://opensource.com/users/dboth"},{default:t(()=>[...n[41]||(n[41]=[s("David Both",-1)])]),_:1}),n[45]||(n[45]=s(" 譯者：",-1)),e(o,{href:"https://github.com/qhwdw"},{default:t(()=>[...n[42]||(n[42]=[s("qhwdw",-1)])]),_:1}),n[46]||(n[46]=s(" 校對：",-1)),e(o,{href:"https://github.com/wxy"},{default:t(()=>[...n[43]||(n[43]=[s("wxy",-1)])]),_:1})]),a("p",null,[n[49]||(n[49]=s("本文由 ",-1)),e(o,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...n[47]||(n[47]=[s("LCTT",-1)])]),_:1}),n[50]||(n[50]=s(" 原創編譯，",-1)),e(o,{href:"https://linux.cn/"},{default:t(()=>[...n[48]||(n[48]=[s("Linux中國",-1)])]),_:1}),n[51]||(n[51]=s(" 榮譽推出",-1))])])}const C=l(c,[["render",u]]);export{x as __pageData,C as default};
